630	// mergeSearchResults merges responses from multiple cells into one, combining
631	// results, stats, and repo_stats. Results are sorted by Score (descending) for
632	// global relevance ranking and truncated to limit. Individual cell errors are
633	// logged and skipped, but if ALL cells fail the error is surfaced.
634	func mergeSearchResults(ctx context.Context, limit int, results []cellCallResult[*codesearch.SearchResponse]) (*codesearch.SearchResponse, error) {
635		merged := &codesearch.SearchResponse{}
636		var lastErr error
637		successCount := 0
638		for _, r := range results {
639			if r.err != nil {
640				lastErr = r.err
641				continue
642			}
643			if r.value == nil {
644				continue
645			}
646			successCount++
647			merged.Results = append(merged.Results, r.value.Results...)
648			merged.RepoStats = append(merged.RepoStats, r.value.RepoStats...)
649			merged.Stats.TotalMatches += r.value.Stats.TotalMatches
650			merged.Stats.TotalFiles += r.value.Stats.TotalFiles
651			merged.Stats.ReposSearched += r.value.Stats.ReposSearched
652			if r.value.Stats.DurationMs > merged.Stats.DurationMs {
653				merged.Stats.DurationMs = r.value.Stats.DurationMs // wall-clock = slowest cell
654			}
655			if merged.Query == "" {
656				merged.Query = r.value.Query
657			}
658		}
659	
660		if successCount == 0 && lastErr != nil {
661			return nil, fmt.Errorf("code search failed: %w", lastErr)
662		}
663	
664		// Track partial failures so consumers (especially --json) can see them.
665		var failedJurisdictions []string
666		for _, r := range results {
667			if r.err == nil {
668				continue
669			}
670			failedJurisdictions = append(failedJurisdictions, r.group.label())
671		}
672		if len(failedJurisdictions) > 0 {
673			logging.Warn(ctx, "code search partial failure; results may be incomplete",
674				"succeeded", successCount,
675				"total", len(results),
676				"failed_cells", failedJurisdictions)
677		}
678	
679		// Sort by score descending so results are globally ranked by relevance,
680		// not grouped by whichever cell returned first. Stable sort with a
681		// tiebreaker keeps --json output deterministic across runs.
682		sort.SliceStable(merged.Results, func(i, j int) bool {
683			a, b := merged.Results[i], merged.Results[j]
684			if a.Score != b.Score {
685				return a.Score > b.Score
686			}
687			if a.Repo != b.Repo {
688				return a.Repo < b.Repo
689			}
690			if a.Path != b.Path {
691				return a.Path < b.Path
692			}
693			return a.Line < b.Line
694		})
695	
696		// Deduplicate results that may appear from overlapping cells (e.g. a repo
697		// with empty jurisdiction searched via both home and explicit cell).
698		seen := make(map[string]bool, len(merged.Results))
699		deduped := merged.Results[:0]
700		for _, r := range merged.Results {
701			key := r.Repo + "\x00" + r.Path + "\x00" + fmt.Sprintf("%d:%d", r.Line, r.Column)
702			if seen[key] {
703				continue
704			}
705			seen[key] = true
706			deduped = append(deduped, r)
707		}
708		merged.Results = deduped
709	
710		// Deduplicate RepoStats by repo name, summing match/file counts.
711		repoStatsMap := make(map[string]*codesearch.RepoStats, len(merged.RepoStats))
712		var dedupedStats []codesearch.RepoStats
713		for _, rs := range merged.RepoStats {
714			if existing, ok := repoStatsMap[rs.Repo]; ok {
715				existing.MatchCount += rs.MatchCount
716				existing.FileCount += rs.FileCount
717			} else {
718				entry := rs // copy
719				repoStatsMap[rs.Repo] = &entry
720				dedupedStats = append(dedupedStats, entry)
721			}
722		}
723		// Write back merged values.
724		for i := range dedupedStats {
725			if m, ok := repoStatsMap[dedupedStats[i].Repo]; ok {
726				dedupedStats[i] = *m
727			}
728		}
729		merged.RepoStats = dedupedStats
730	
731		// Stats are preserved as the sum of per-cell peregrine stats — they
732		// reflect the true totals (including zero-match repos and per-cell
733		// truncation), not just the deduped result slice.
734	
735		// Cap to the caller's requested limit.
736		if limit > 0 && len(merged.Results) > limit {
737			merged.Results = merged.Results[:limit]
738		}
739	
740		// Surface partial failures in the response so JSON consumers can detect them.
741		merged.FailedJurisdictions = failedJurisdictions
742	
743		return merged, nil
744	}
