126	// resolveCellBaseURLs fills each group's baseURL from the cluster catalog,
127	// joining on ClusterSlug ↔ Cluster.Slug. Best-effort: on a catalog error or
128	// timeout (bounded by cellResolveTimeout, like resolveRepoCellTarget — a hung
129	// core must not stall the command) or a missing/incomplete cluster row, the
130	// group keeps baseURL "" and falls back to jurisdiction routing — a degraded
131	// catalog must not sink the fan-out.
132	func resolveCellBaseURLs(ctx context.Context, c cellCoreClient, cells []cellGroup) {
133		ctx, cancel := context.WithTimeout(ctx, cellResolveTimeout)
134		defer cancel()
135	
136		clusters, err := c.ListClusters(ctx)
137		if err != nil {
138			logging.Debug(ctx, "cell fan-out: list clusters failed, using jurisdiction routing", "error", err.Error())
139			return
140		}
141		bySlug := make(map[string]coreapi.Cluster, len(clusters.Clusters))
142		byJurisdiction := make(map[string]coreapi.Cluster, len(clusters.Clusters))
143		for _, cl := range clusters.Clusters {
144			bySlug[strings.ToLower(strings.TrimSpace(cl.Slug))] = cl
145			// Prefer the default cluster per jurisdiction — matches the auth
146			// layer's resolution when routing by jurisdiction alone. A non-default
147			// cluster is kept only when no default has been seen yet.
148			j := strings.ToLower(strings.TrimSpace(cl.Jurisdiction))
149			if j != "" {
150				existing, exists := byJurisdiction[j]
151				if !exists || (cl.IsDefault && !existing.IsDefault) {
152					byJurisdiction[j] = cl
153				}
154			}
155		}
156		for i := range cells {
157			cl, ok := bySlug[cells[i].clusterSlug]
158			if !ok && cells[i].cell != "" {
159				// Try matching the group's cell name against catalog apiUrl
160				// hosts (e.g. cell "aws-eu-central-1" matches
161				// "https://aws-eu-central-1.api.entire.io"). This is more
162				// precise than jurisdiction when a jurisdiction has multiple
163				// cells — mirroring matchClusterByHost in cell_target.go.
164				cl, ok = matchClusterByCellInURL(clusters.Clusters, cells[i].cell)
165			}
166			if !ok && cells[i].jurisdiction != "" {
167				// Last resort: jurisdiction-level fallback using the default
168				// cluster. Less precise, but still routes to the right
169				// jurisdiction when the cell name doesn't appear in any URL.
170				cl, ok = byJurisdiction[cells[i].jurisdiction]
171			}
172			if !ok {
173				logging.Debug(ctx, "cell fan-out: cluster not in catalog, using jurisdiction routing",
174					"cluster_slug", cells[i].clusterSlug, "cell", cells[i].cell)
175				continue
176			}
177			// A concrete baseURL needs a jurisdiction to mint the matching token
178			// for — mirroring resolveRepoCellTarget, which refuses a target unless
179			// both are present. Setting baseURL with an unknown jurisdiction would
180			// dial the cell with a home-jurisdiction token.
181			jurisdiction := cells[i].jurisdiction
182			if j := strings.ToLower(strings.TrimSpace(cl.Jurisdiction)); j != "" {
183				jurisdiction = j
184			}
185			if jurisdiction == "" {
186				logging.Debug(ctx, "cell fan-out: no jurisdiction for cluster, using home routing",
187					"cluster_slug", cells[i].clusterSlug, "cell", cells[i].cell)
188				continue
189			}
190			cells[i].jurisdiction = jurisdiction
191			cells[i].baseURL = strings.TrimRight(strings.TrimSpace(cl.ApiUrl.Or("")), "/")
192		}
193	}
