196	// host contains the cell name as a prefix (e.g. cell "aws-eu-central-1"
197	// matches "https://aws-eu-central-1.api.entire.io"). This is more precise
198	// than a jurisdiction-level fallback when multiple clusters share a
199	// jurisdiction — each cluster serves a different cell.
200	func matchClusterByCellInURL(clusters []coreapi.Cluster, cell string) (coreapi.Cluster, bool) {
201		prefix := strings.ToLower(strings.TrimSpace(cell)) + "."
202		for _, cl := range clusters {
203			for _, rawURL := range []string{cl.ApiUrl.Or(""), cl.PublicUrl} {
204				rawURL = strings.TrimSpace(rawURL)
